def execute_searches(client: HttpClient, providers: list[str], queries: list[str], limit: int, start_year: int | None, end_year: int | None, mailto: str, oai_endpoint: str = "") -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    records: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
